<?php
declare(strict_types=1);
if (!defined('CWP_BOOT')) { http_response_code(404); exit; }
function proposals_schema(string $prefix): array {
    if(!preg_match('/^[a-zA-Z][a-zA-Z0-9_]{1,19}$/D',$prefix))throw new InvalidArgumentException('Invalid prefix.');
    $engine=' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci';return [
    'proposals'=>'CREATE TABLE `'.$prefix.'proposals` (id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,client_id INT UNSIGNED NOT NULL,title VARCHAR(160) NOT NULL,status VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,current_version INT UNSIGNED NOT NULL,request_key CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,request_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,created_by INT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,sent_at DATETIME NULL,decided_at DATETIME NULL,INDEX proposals_client(client_id,status),INDEX proposals_status(status,created_at))'.$engine,
    'proposal_versions'=>'CREATE TABLE `'.$prefix.'proposal_versions` (id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,proposal_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,version INT UNSIGNED NOT NULL,title VARCHAR(160) NOT NULL,deliverables MEDIUMTEXT NOT NULL,exclusions TEXT NOT NULL,schedule_notes TEXT NOT NULL,milestones MEDIUMTEXT NOT NULL,content_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,created_by INT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,UNIQUE proposal_version(proposal_id,version),UNIQUE proposal_content(proposal_id,content_hash))'.$engine,
    'proposal_events'=>'CREATE TABLE `'.$prefix.'proposal_events` (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,proposal_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,event VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,actor_type VARCHAR(10) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,actor_id INT UNSIGNED NOT NULL,detail VARCHAR(500) NOT NULL DEFAULT \'\',created_at DATETIME NOT NULL,INDEX proposal_history(proposal_id,id))'.$engine,
    'proposal_decisions'=>'CREATE TABLE `'.$prefix.'proposal_decisions` (id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,proposal_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,version INT UNSIGNED NOT NULL,decision VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,client_id INT UNSIGNED NOT NULL,note VARCHAR(2000) NOT NULL DEFAULT \'\',created_at DATETIME NOT NULL,UNIQUE proposal_version_decision(proposal_id,version))'.$engine];
}
